const app = getApp();
const store = require('../../utils/store');

Page({
  data: {
    events: [],
    filter: 'all',
    types: app.globalData.types,
    statuses: app.globalData.statuses
  },

  onShow() {
    this.loadData();
  },

  loadData() {
    const events = store.getEventsSync().map(e => this.enrich(e));
    this.setData({ events });
    store.refresh().then(() => {
      const ev2 = store.getEventsSync().map(e => this.enrich(e));
      this.setData({ events: ev2 });
    });
  },

  enrich(e) {
    const t = app.globalData.types.find(x => x.key === e.type);
    const s = app.globalData.statuses.find(x => x.key === e.status);
    return { ...e, typeLabel: t ? t.label : e.type, statusLabel: s ? s.label : e.status };
  },

  onFilterChange(e) {
    this.setData({ filter: e.currentTarget.dataset.type });
  },

  goDetail(e) {
    const id = e.currentTarget.dataset.id;
    wx.navigateTo({ url: '/pages/eventDetail/eventDetail?id=' + id });
  },

  goAdd() {
    wx.navigateTo({ url: '/pages/addEvent/addEvent' });
  }
});
